import json
def w(n,o): json.dump(o,open('dup_work/airspecs/%s.json'%n,'w',encoding='utf8'),ensure_ascii=False)
w('afr',{"airline":"Air France","alcohol":{"checked":"22 November 2026","answer":"Air France allows alcohol in checked baggage (5 litres per person for drinks of 24% to 70%) but not in the cabin, except duty-free alcohol bought after security and kept in a sealed bag. Homemade alcohol and anything above 70% are not allowed.","sections":[{"h":"🍷 What Air France says about alcohol","p":"From the Air France page \"Liquides, crèmes - boissons alcoolisées, combustibles, liquides inflammables - Poudres\" (in French), read on 22 November 2026.","table":{"head":["Question","Air France rule"],"rows":[["In the cabin","No, except alcohol bought in airport duty-free shops after security and placed in a sealed bag"],["In the hold (checked)","Yes: up to 5 litres per person for drinks between 24% and 70% alcohol"],["Per container","For 24% to 70%, at most 5 litres per container and per person"],["Above 70%, or homemade","Not allowed"],["Packaging","Retail packaging, properly closed"],["Prior approval","Not needed"],["Destination","Extra restrictions may apply depending on where you fly"]]},"list":["<strong>Not on the page:</strong> the page does not give a limit for drinks of 24% or less, so ask Air France or check the destination's customs rules."]}],"faq":[["Can I take alcohol in my Air France cabin bag?","Not normally. The exception is alcohol bought in a duty-free shop at the airport after security and kept in a sealed bag."],["How much alcohol can I check on Air France?","Up to 5 litres per person for drinks between 24% and 70% alcohol; drinks above 70% and homemade alcohol are not allowed."]],"sources":[["https://wwws.airfrance.fr/information/bagages/popin_produits-interdits-et-reglementes/produits-interdits-et-reglementes-11","Air France &mdash; Liquides, boissons alcoolisées (produits interdits et réglementés)"]]}})
w('jal',{"airline":"Japan Airlines","alcohol":{"checked":"22 November 2026","answer":"JAL allows alcohol in carry-on or checked baggage: drinks of 24% or less have no limit, drinks above 24% and under 70% are limited to five litres per person, and anything over 70% is prohibited.","sections":[{"h":"🍷 What Japan Airlines says about alcohol","p":"From the JAL international-flights page \"About the restricted articles in checked and carry-on baggage\", read on 22 November 2026.","table":{"head":["Question","JAL rule"],"rows":[["24% alcohol or less","No limit"],["Above 24% and under 70%","Five litres per person"],["Over 70%","Prohibited in carry-on and checked baggage"],["Where to carry it","Carry-on or checked; JAL strongly recommends glass bottles go in carry-on because they are fragile"],["Cabin liquids","On international flights containers must hold 100 ml or less, in one transparent re-sealable bag of up to one litre"]]},"list":["<strong>Not on the page:</strong> the section read does not explain how bottles bought at foreign duty-free shops are handled at a Japanese connection."]}],"faq":[["How much alcohol can I take on a JAL international flight?","No limit up to 24% alcohol; five litres per person above 24% and under 70%; over 70% is prohibited."],["Should I pack a glass bottle in carry-on or checked bags on JAL?","JAL allows both but strongly recommends carry-on for glass bottles because they are fragile."]],"sources":[["https://www.jal.co.jp/jp/en/inter/baggage/limit/attention/","Japan Airlines &mdash; Restricted articles in checked and carry-on baggage (international flights)"]]}})
w('vaus',{"airline":"Virgin Australia","alcohol":{"checked":"22 November 2026","answer":"Virgin Australia permits alcohol in carry-on or checked baggage in retail packaging, up to a maximum net total of 5 litres per person and not above 70% alcohol. You may not drink alcohol you carry on board.","sections":[{"h":"🍷 What Virgin Australia says about alcohol","p":"From the Virgin Australia Dangerous goods page, read on 22 November 2026.","table":{"head":["Question","Virgin Australia rule"],"rows":[["Carry-on baggage","Permitted"],["Checked baggage","Permitted"],["Packaging","Retail packaging"],["Quantity","Maximum net total of 5 litres per person"],["Strength","Must not be more than 70% alcohol by volume"],["Operator approval","Not required"],["Drinking it on board","Not permitted for alcohol you carry"],["International flights","Liquid, aerosol and gel limits apply in carry-on; the page refers to the Department of Infrastructure"]]},"list":["<strong>Not on the page:</strong> this page gives no separate rule for drinks of 24% or less."]}],"faq":[["How much alcohol can I take on Virgin Australia?","A maximum net total of 5 litres per person, in retail packaging, and no more than 70% alcohol by volume."],["Can I drink my own alcohol on a Virgin Australia flight?","No. The Dangerous goods page says consumption of alcohol carried on board is not permitted."]],"sources":[["https://www.virginaustralia.com/au/en/travel-info/baggage/dangerous-goods/","Virgin Australia &mdash; Dangerous goods"]]}})
w('eth',{"airline":"Etihad Airways","alcohol":{"checked":"22 November 2026","answer":"Etihad lists alcoholic beverages above 70% alcohol by volume as not permitted in cabin or checked baggage. The page read gives no quantity limit for drinks at or below 70%.","sections":[{"h":"🍷 What Etihad says about alcohol","p":"From the Etihad page \"Prohibited items and what you can take on board\", read on 22 November 2026.","table":{"head":["Question","Etihad rule"],"rows":[["Above 70% alcohol by volume","Not permitted in cabin or checked baggage"],["Flammable liquids such as alcohol or ethanol (fuel, thinner)","Not permitted in cabin or checked baggage"],["Drinks at or below 70%","No quantity limit is stated on this page"]]},"list":["<strong>Not on the page:</strong> a litre limit, a rule for duty-free bottles and a rule for drinking your own alcohol are not on this page. Check the Conditions of Carriage and Etihad before you fly."]}],"faq":[["What alcohol is banned on Etihad flights?","Etihad does not permit alcoholic beverages above 70% alcohol by volume in cabin or checked baggage."],["Does Etihad give a litre limit for alcohol?","Not on its Prohibited items page, so ask Etihad or check its Conditions of Carriage."]],"sources":[["https://www.etihad.com/en/help/baggage-information/prohibited-items","Etihad Airways &mdash; Prohibited items and what you can take on board"]]}})
